"""Cổng soát. Hai mức, tách bạch theo nguồn gốc luật (bài học Kinmireva 11/09):
  BLOCK  — chỉ khi luật đứng trên sự thật FoxEra đã kiểm (TM đã dính, luật lane đã chốt, trùng chữ ký).
  REVIEW — mọi thứ do Claude tự đặt hoặc chỉ là nghi vấn: in cờ + lý do, KHÔNG loại.
Soát MỌI lớp chữ (S8). Vi phạm chỉ nằm trong HÌNH (logo/emblem) thì không máy nào bắt được → checklist mắt."""
from __future__ import annotations
import re
import re as _re
from pathlib import Path

from .schema import canon


_STATIC_POSE = {"sitting", "sits", "standing", "stands", "posing", "poses", "looking", "looks",
                "lying", "lies", "resting", "rests", "perched", "facing", "staring"}
_LABEL_FILLER = {"the", "and", "of", "a", "with", "for"}          # từ đệm không làm chữ thành câu
# Từ cho thấy CÓ NGƯỜI đang nói — người mặc về mình, hoặc người tặng với người nhận.
_VOICE_WORDS = {"i", "im", "i'm", "me", "my", "mine", "you", "your", "we", "our", "us", "just", "still", "not", "dont",
                "don't", "cant", "can't", "always", "never", "only", "mom", "dad", "mama", "papa", "nana", "grandma",
                "grandpa", "wife", "husband", "est", "since", "born", "home", "club", "life", "official", "certified"}


def sig_key(idea: dict, brand) -> str:
    """Chữ ký = các trường cấu trúc + lens (khi brand kể chuyện). Cùng loài, cùng tư thế nhưng
    câu chuyện khác là ý KHÁC — đó là cách thoát đơn điệu mà không mở cửa cho trùng lặp."""
    fields = list(brand.signature_fields)
    if "lens" in idea["signature"] and "lens" not in fields:
        fields.append("lens")
    return brand.brand + "|" + "|".join(f"{f}={idea['signature'][f]}" for f in fields)


def _all_text(idea: dict) -> str:
    parts = [idea["name"], idea["concept_vi"], idea.get("buyer", ""), idea.get("occasion", "")]
    for s in idea["sides"].values():
        parts += [s["subject"], s["action"], s["setting"], *s["supporting"], s["text_overlay"] or ""]
    return " \n ".join(parts)


def _hit(term: str, text: str) -> bool:
    return re.search(r"(?<![a-z0-9])" + re.escape(term.lower()) + r"(?![a-z0-9])", text.lower()) is not None


STOP = {"the", "a", "of", "and", "golf", "shirt", "polo", "funny", "hawaiian", "pattern",
        "hoodie", "sun", "camo", "mens", "men", "tee", "hat", "cap"}


def load_catalog_rows(rows: list) -> list:
    """Đổi các dòng 'CODE|Tên' thành bảng chống trùng. Dùng chung cho file tĩnh và feed live."""
    out = []
    for line in rows:
        if "|" in line and not line.startswith("#"):
            code, name = line.split("|", 1)
            toks = set(canon(name).split("_")) - STOP
            if toks:
                out.append((code.strip(), name.strip(), toks))
    return out


def load_catalog(brand, home: Path) -> list:
    """Danh mục hàng ĐANG BÁN để chống trùng. Hai nguồn, cộng dồn.

    17/09: board «GerberaPrints Catalog» có ~1.986 thẻ tên SKU + tên thiết kế, cập nhật bởi chính đội —
    đầy đủ và sống hơn file .txt phải xuất tay. Khai `catalog_board` trong cartridge thì lấy cả hai;
    board hỏng thì KHÔNG im lặng coi như không trùng (S4), mà báo và vẫn dùng file nếu có.
    """
    rows = []
    f = brand.raw.get("catalog_names_file")
    if f:
        p = home / f
        if not p.exists():
            raise FileNotFoundError(f"Không đọc được catalog chống trùng {p} (S4: không đọc được ≠ không trùng)")
        rows += load_catalog_rows(p.read_text(encoding="utf-8").splitlines())
    cb = brand.raw.get("catalog_board")
    if cb:
        from . import feedback as _fb
        try:
            lists, cards = _fb.fetch_board_cards(cb["board"])
        except Exception as e:                                        # noqa: BLE001
            # S4: không đọc được ≠ không trùng. Còn file cục bộ thì vẫn chống trùng được — KÊU rồi đi tiếp.
            # Không còn gì cả thì DỪNG, vì lúc đó lượt này đang chạy mù hoàn toàn.
            if rows:
                print(f"  ⚠ catalog_board {cb['board']} không đọc được ({type(e).__name__}) — "
                      f"chỉ chống trùng bằng file cục bộ ({len(rows)} tên)")
                return rows
            raise FeedbackCatalogError(
                f"Khai catalog_board nhưng không đọc được board {cb['board']}: {type(e).__name__}, "
                "và không có file catalog cục bộ. Không đọc được ≠ không trùng — sửa khoá Trello rồi chạy lại.") from e
        bo = [x.lower() for x in cb.get("skip_lists", [])]
        # Tên thẻ dạng «PM-PB0456-Block Party» hoặc «PW-PB0043»: tách mã và tên thiết kế thành
        # đúng định dạng 'CODE|Tên' mà load_catalog_rows đang dùng cho file tĩnh.
        ten = []
        for c in cards:
            if any(b in (lists.get(c.get("idList")) or "").lower() for b in bo):
                continue
            n = (c.get("name") or "").strip()
            if not n:
                continue
            m = _re.match(r"^([A-Z]{2}-[A-Z]{2}\d{3,}[A-Za-z]?)\s*[-–—]?\s*(.*)$", n)
            code, ten_tk = (m.group(1), m.group(2).strip()) if m else ("", n)
            ten.append(f"{code}|{ten_tk or code}")
        rows += load_catalog_rows(ten)
    return rows


class FeedbackCatalogError(RuntimeError):
    pass


def catalog_matches(idea: dict, catalog: list) -> list:
    mine = set(canon(idea["name"]).split("_"))
    for v in idea["signature"].values():
        mine |= set(v.split("_"))
    mine -= {"the", "a", "of", "and", "golf", ""}
    own_name = canon(idea["name"])
    hits = []
    for code, name, toks in catalog:
        inter = mine & toks
        if len(toks) == 1:                      # tên 1 từ ("Texas", "Patriot"): chỉ khớp khi TRÙNG TÊN — tránh màn hình đỏ sẵn
            hit = own_name == next(iter(toks))
        elif len(toks) == 2:
            hit = toks <= mine
        else:
            hit = len(inter) >= 2 and len(inter) / len(toks) >= 0.5
        if hit:
            hits.append(f"{code} '{name}'")
    return hits[:3]


def run_gates(idea: dict, brand, seen: set, catalog: list, cores: dict | None = None) -> tuple[str, list, list]:
    """→ (verdict, blocks, reviews). verdict ∈ READY | REVIEW | DROPPED"""
    blocks, reviews = [], []
    key = sig_key(idea, brand)
    if key in seen:
        blocks.append(f"TRÙNG chữ ký {key}")
    if cores:
        from .ledger import _core_of
        core = _core_of(key)
        if core and core in cores:
            blocks.append(f"TRÙNG LÕI (cùng chủ thể + tư thế, chỉ khác enum) với ý '{cores[core]}' — {core}")
    text = _all_text(idea)
    bl = brand.blocklist
    for t in bl.get("tm_block", []):
        if _hit(t["term"], text):
            blocks.append(f"TM '{t['term']}' — {t['why']}")
    for t in bl.get("tm_review", []):
        if _hit(t["term"], text):
            reviews.append(f"TM? '{t['term']}' — {t['why']}")
    for r in bl.get("block_patterns", []):
        if re.search(r["regex"], text, flags=re.I):
            blocks.append(r["why"])
    for r in bl.get("review_patterns", []):
        if re.search(r["regex"], text, flags=re.I):
            reviews.append(r["why"])
    lane = idea.get("lane")
    if lane and lane in brand.lane_rules:
        allowed = brand.lane_rules[lane].get("content_level")
        if allowed and idea.get("content_level") not in allowed:
            blocks.append(f"lane {lane} chỉ nhận {allowed}, ý này {idea.get('content_level')} — {brand.lane_rules[lane].get('why','')}")
    # Roster chỉ là KẾ HOẠCH, tín hiệu cầu là SỰ THẬT ĐO ĐƯỢC. Cờ này chỉ bật khi ý
    # KHÔNG có tín hiệu nào chống lưng — loài ngoài roster mà sổ quyết định hoặc lỗ trống
    # catalogue đã chỉ ra thì cắm cờ là sai, và cắm cho 15/18 thẻ thì cờ mất hết ý nghĩa
    # (đúng bẫy "màn hình đỏ sẵn" trong hồ sơ sự cố 11/09).
    if brand.roster and idea.get("evidence") in (None, "", "HYPOTHESIS"):
        rc = {canon(s) for s in brand.roster.get("species", [])}
        sp = idea["signature"].get("species_canonical")
        # 'largemouth_bass' phải khớp roster 'largemouth'. So khớp theo TỪ, không đòi
        # trùng chuỗi tuyệt đối — nếu không thì cờ bật oan cho đúng loài trong roster.
        toks = set(str(sp).split("_"))
        hit = any(r == sp or set(r.split("_")) <= toks or toks <= set(r.split("_")) for r in rc)
        if sp and not hit:
            reviews.append(f"'{sp}' vừa NGOÀI roster {sorted(rc)} vừa KHÔNG có tín hiệu cầu "
                           f"— đây là ý tự nghĩ ra, người duyệt quyết")
    # Chép NGUYÊN CỤM tên/câu của đối thủ = loại (Etsy learnings: VERBATIM_PHRASE → DROP; CONCEPT_FORMAT → OK).
    # Danh sách cụm: cartridge `competitor_phrases` + cụm trong nháy đơn bóc từ bản tin research.
    text_all = _all_text(idea).lower()
    for ph in (brand.raw.get("competitor_phrases") or []) + list(getattr(brand, "_research_phrases", []) or []):
        p = str(ph).lower().strip()
        if len(p) >= 12 and p in text_all:
            blocks.append(f"chép nguyên cụm của đối thủ: '{ph}' — chuyển ý tưởng (concept) thì được, chép chữ thì không")
    st = idea.get("story") or {}
    if re.search(r"[ăâđêôơưÀ-ỹ]", " ".join(str(st.get(k) or "") for k in ("insight", "line", "why_now"))):
        reviews.append("khối câu chuyện có lẫn tiếng Việt — phần này người mua Mỹ đọc, phải thuần tiếng Anh")
    # DẤU VẾT NGƯỜI — luật của lớp câu chuyện, ép bằng code sau khi dặn lời thất bại (ảnh 16/09).
    trace = brand.raw.get("human_trace_words") or []
    if trace and idea.get("layout") in ("FRONT_ONLY", "FRONT_BACK", "LEFT_CHEST"):
        c = idea.get("contract") or {}
        pool = " ".join(c.get("required") or []) + " " + " ".join(
            " ".join(s.get("supporting") or []) + " " + s.get("action", "") for s in idea["sides"].values())
        if not any(wd in pool.lower() for wd in trace):
            blocks.append("không có dấu vết người/đồ nghề nào trong contract.required hay cảnh — sẽ ra chân dung "
                          "con vật/nhân vật đứng một mình (ảnh 16/09 chứng minh), không kể được chuyện")
    # CHỖ CHO KHÁCH ĐIỀN — brand quà tặng khai `personalize: required`. Thiếu = REVIEW, không DROP:
    # ý vẫn dùng được, nhưng đang bỏ qua đòn bẩy mà bản tin Etsy 17/09 đo được (90,9% vs 62,5% giữ giá).
    if brand.raw.get("personalize") == "required" and idea.get("layout") in ("FRONT_ONLY", "FRONT_BACK", "LEFT_CHEST", "EMBROIDERY"):
        pz = idea.get("personalize") or {}
        if not pz or pz.get("kind") in (None, "none"):
            reviews.append("chưa có chỗ cho khách điền (tên / tên thú / EST năm / bang) — Etsy 17/09 đo: listing nhận chữ "
                           "khách tự nhập giữ nguyên giá 10/11, không nhận 5/8. Người tặng quà mua cái CÓ TÊN.")
    # CHỮ CHỈ DÁN NHÃN — ảnh 17/09 «FREEDOM MELONS» trên hai quả dưa: chữ gọi tên vật, không phải câu người mặc
    # nói hay người tặng nói. Thị trường bán «just a spooky goose» (người mặc tự giễu), «Emma» (tên người nhận).
    # Chỉ áp cho brand khai `text_must_speak: true`. GritFell in tên loài trên banner theo đúng ngôn ngữ
    # field-guide («SPECKLED TROUT») — đó là DNA, không phải lỗi. Gerbera (câu đùa) và Kinmireva (quà) thì cần.
    # 01/10: `text_must_speak: when_present` la CHUOI -> truthy -> cong van chay y het nhu `true`.
    # Doi cartridge ma khong doi code o day = thay doi KHONG CO TAC DUNG. Xu ly tuong minh:
    #   true | when_present -> kiem khi CO chu (vong duoi da `if not t: continue`)
    #   false | khong khai  -> khong kiem
    _tms = brand.raw.get("text_must_speak")
    _bat_tms = _tms is True or (isinstance(_tms, str) and _tms.strip().lower() in ("true", "when_present"))
    for sname, sd in ((idea.get("sides") or {}).items() if _bat_tms else ()):
        t = (sd.get("text_overlay") or "").strip().lower()
        if not t:
            continue
        words = {w for w in _re.findall(r"[a-z']+", t) if len(w) > 2}
        subj = " ".join([sd.get("subject") or "", " ".join(sd.get("supporting") or [])]).lower()
        stem = lambda w: w[:-1] if w.endswith("s") and len(w) > 3 else w
        # nhãn = (gọi đúng vật đang vẽ) VÀ (không có giọng ai nói). «FREEDOM MELONS»: 'melon' nằm trong
        # 'watermelons', không có tôi/bạn/just/mom… → nhãn. «just a spooky goose»: có 'just' → giọng người mặc.
        names_it = any(stem(w) in subj for w in words if w not in _LABEL_FILLER)
        has_voice = any(w in _VOICE_WORDS for w in words)
        if words and names_it and not has_voice:
            reviews.append(f"chữ in «{sd.get('text_overlay')}» chỉ gọi tên vật trong hình — không phải câu người mặc nói "
                           "về mình hay câu người tặng nói với người nhận; chưa chạm tới ai")
    # QUÀ TẶNG — người mua và người nhận là hai người khác nhau. Công thức của chính dự án Etsy
    # (F01 IMPROVEMENT MAP 12/09 §1.7): Niche + Recipient + Occasion + Emotion + Product + Personalization.
    # Thiếu người nhận hoặc thiếu cảm xúc = ý chưa nói được nó dành cho ai, vì sao người kia cảm động.
    if brand.raw.get("gift_intent") == "required":
        thieu = [t for t, v in (("người nhận", idea.get("recipient")), ("cảm xúc trao đi", idea.get("emotion")),
                                ("dịp", idea.get("occasion"))) if not (v or "").strip()]
        if thieu:
            reviews.append("chưa trả lời được cho ai / vì sao: thiếu " + ", ".join(thieu)
                           + " — người tặng quà mua CẢM XÚC họ muốn trao, không mua hình đẹp")
    # ĐIỂM CHẠM — 2.38.0. Slot được giao một DỊP mà ý vẫn 'evergreen' / dịp chung chung = trôi khỏi dịp:
    # đúng thứ làm 3/4 thẻ 02/10 không có câu chuyện. REVIEW, không DROP — ý vẫn dùng được, người duyệt quyết.
    mo = idea.get("moment")
    if mo:
        toks = [w for w in _re.findall(r"[a-z]{4,}", (mo.get("label") or "").lower()) if w not in ("gifting", "season")]
        why = ((idea.get("story") or {}).get("why_now") or "").lower()
        occ = (idea.get("occasion") or "").lower()
        if toks and not any(t in why or t in occ for t in toks):
            reviews.append(f"trôi khỏi dịp: slot giao {mo.get('label')} mà why_now/occasion không nhắc tới — "
                           "ý không chạm được người mua đúng lúc họ đang tìm quà")
        if _re.search(r"everyday|no occasion|any day|any occasion|evergreen", occ + " " + why):
            reviews.append(f"dịp chung chung ('{idea.get('occasion')}') trong khi slot có dịp {mo.get('label')}")
    # HÀNH ĐỘNG LÀ ĐIỂM KHÁC BIỆT — F01 IDEA 11: không phải "mèo với quyển sách" mà "mèo giấu sách quá hạn".
    # Khớp với phép đo riêng 16/09: chân dung con vật đứng một mình không kể được chuyện.
    for sname, sd in (idea.get("sides") or {}).items():
        act = (sd.get("action") or "").strip().lower()
        if act and not any(_re.search(rf"\b{w}\b", act) for w in _STATIC_POSE):
            continue
        if act and len(act.split()) <= 6:
            reviews.append(f"hành động «{sd.get('action')}» là TƯ THẾ, không phải việc đang diễn ra — "
                           "đổi sang một khoảnh khắc kể lại được (F01 IDEA 11: 'mèo giấu quyển sách quá hạn')")
    # CHỐNG CLONE THEO CƠ CHẾ — F02 Blind Spot 4. Cổng trùng lõi bắt trùng chủ thể+tư thế; cổng này bắt
    # thứ tinh vi hơn: cùng MỘT cơ chế lặp đi lặp lại thì bộ sưu tập chỉ là một ý đổi đạo cụ.
    if brand.raw.get("require_mechanism"):
        if not idea.get("mechanism"):
            reviews.append("chưa khai cơ chế dựng hình — không biết ý này khác 20 listing kia ở CƠ CHẾ nào "
                           "hay chỉ đổi loài/hoa/màu (F02 Blind Spot 4: clone risk)")
        if len(idea.get("expansion") or []) < 3:
            reviews.append("chưa nêu đủ 3 hướng mở rộng — ý không thành bộ sưu tập được thì chỉ là một listing lẻ")
    # HỢP LÝ VẬT LÝ — đo từ 62 ảnh GritFell bị loại 30/09. Xem plausibility.py, mỗi kiểm ứng ≥2 ảnh thật.
    from . import plausibility as _pl
    reviews += _pl.check(idea, brand)
    reviews += _pl.rang_buoc_san_xuat(idea, brand)
    if idea.get("layout_downgraded"):
        reviews.append(idea["layout_downgraded"] + " — ý vẫn dùng được, nhưng mất phần lưng")
    pg = idea.get("policy_guess")
    if pg in ("L2", "L3"):
        reviews.append(f"rủi ro quảng cáo {pg}: chỉ organic, KHÔNG chạy paid (thang Meta của GP Report Ads) — vẫn bán được, nhưng không phải động cơ tăng trưởng")
    for m in catalog_matches(idea, catalog):
        reviews.append(f"gần giống mẫu đã có {m} — chủ đích mở rộng thì giữ, không thì bỏ")
    verdict = "DROPPED" if blocks else ("REVIEW" if reviews else "READY")
    return verdict, blocks, reviews
